  ja: { "change-rate": "200から150への変化は-50、変化率は-25％です。率の基準は元の値で、元の値が0の場合は計算できません。", discount: "50,000に20％の割引を適用すると割引額は10,000、計算上の販売価格は40,000です。送料・税・クーポンは含みません。", cagr: "100から121への2年間の変化は、年10％の複利成長に相当します。毎年の実績が10％だったという意味ではありません。", "simple-interest": "元本1,000,000に年10％の単利を5年間適用すると、利息は500,000、合計は1,500,000です。利息は元本だけを基準にします。", "compound-interest": "元本1,000,000、年10％、年1回の複利を5年間適用すると最終額は1,610,510です。税・手数料・追加預入は含みません。" },
  zh: { "change-rate": "从200变为150，变化量为-50、变化率为-25%；变化率以原值为基准，原值为0时无法计算。", discount: "标价50,000打八折后折扣额为10,000，计算售价为40,000；不含运费、税费或优惠券。", cagr: "两年间从100增至121，相当于年复合增长率10%；这不表示每年实际回报都为10%。", "simple-interest": "本金1,000,000按年利率10%计算5年单利，利息为500,000，总额为1,500,000；利息只按本金计算。", "compound-interest": "本金1,000,000按年利率10%、每年复利一次计算5年，终值为1,610,510；不含税费及追加投入。" },
  "zh-tw": { "change-rate": "從200變為150，變化量為-50、變化率為-25%；變化率以原值為基準，原值為0時無法計算。", discount: "定價50,000打八折後折扣額為10,000，計算售價為40,000；不含運費、稅費或優惠券。", cagr: "兩年內從100增至121，相當於年複合成長率10%；不代表每年的實際報酬都是10%。", "simple-interest": "本金1,000,000按年利率10%計算5年單利，利息為500,000，總額為1,500,000；利息只按本金計算。", "compound-interest": "本金1,000,000按年利率10%、每年複利一次計算5年，期末金額為1,610,510；不含稅費及追加投入。" },
  es: { "change-rate": "De 200 a 150, el cambio es −50 y la tasa −25%, tomando el valor inicial como base; con una base de cero no se define la tasa.", discount: "Un descuento del 20% sobre 50.000 reduce 10.000 y deja un precio calculado de 40.000; no incluye envío, impuestos ni cupones.", cagr: "Pasar de 100 a 121 en dos años equivale a una tasa compuesta anual del 10%; no significa que cada año rindiera 10%.", "simple-interest": "Al 10% simple durante cinco años, 1.000.000 genera 500.000 de interés y suma 1.500.000; el interés se calcula solo sobre el principal.", "compound-interest": "Al 10% con capitalización anual durante cinco años, 1.000.000 llega a 1.610.510; se excluyen impuestos, comisiones y aportes adicionales." },
  "pt-br": { "change-rate": "De 200 para 150, a variação é −50 e a taxa é −25%, usando o valor inicial como base; com base zero, a taxa não é definida.", discount: "Um desconto de 20% sobre 50.000 reduz 10.000 e resulta em preço calculado de 40.000; não inclui frete, impostos ou cupons.", cagr: "Ir de 100 a 121 em dois anos equivale a uma taxa composta anual de 10%; isso não significa retorno real de 10% em cada ano.", "simple-interest": "A 10% simples por cinco anos, 1.000.000 rende 500.000 de juros e totaliza 1.500.000; os juros incidem apenas sobre o principal.", "compound-interest": "A 10% com capitalização anual por cinco anos, 1.000.000 chega a 1.610.510; impostos, tarifas e aportes extras ficam de fora." },
